    cells = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (2, 4)]
    if not cells:
        return g
    if axis == "h":
        lo, hi = min(r for r,c,v in cells), max(r for r,c,v in cells)
        # Keep the object's shape and location along the line; place its nearest
        # edge next to the guide line.
        if lo > pos:
            shift = pos + 1 - lo
            stripe = pos + 1 + (hi - lo) + 1
        else:
            shift = pos - 1 - hi
            stripe = pos - 1 - (hi - lo) - 1
        for r in range(h):
            if r != pos:
